/* Fix V6.9: diagnostico en tiempo de ejecucion y ajuste de layout principal */
.tutorial-overlay,.modal-overlay,.side-overlay,.tour-overlay,.screenshot-warning,.toast-reminder{display:none!important}
.main-card-container,.main-content,#planner-container{display:block!important;width:100%!important;min-height:100vh!important;opacity:1!important;visibility:visible!important;z-index:1!important}
#app:has(.side-panel.open) .main-card-container{margin-left:330px!important;width:calc(100% - 330px)!important}
#view-semanal,#view-mensual,#view-diario{display:block!important;width:100%!important;min-height:500px!important}
